{
  "book_code": "JASHER",
  "verses": [
    {
      "chapter": 1,
      "verse": 21,
      "text_ar": "فقال قايين لأخيه هابيل: حقاً إن قتلته اليوم، فمن يطلب دمَك مني؟"
    },
    {
      "chapter": 1,
      "verse": 22,
      "text_ar": "فأجاب هابيل قايين قائلاً: حقاً إن الله الذي صنعنا على الأرض، هو سينتقم لدعواي، وهو سيطلب دمك مني إن قتلتني، لأن الرب هو الديان والحكم، وهو الذي يجازي الإنسان بحسب شره، والرجل الشرير بحسب الشر الذي يفعله على الأرض."
    },
    {
      "chapter": 1,
      "verse": 23,
      "text_ar": "والآن، إن كنت ستقتلني هنا، فحقا إن الله يعلم مقاصدك السرية، وسيدينك على الشر الذي أعلنت أنك ستفعله بي اليوم."
    },
    {
      "chapter": 1,
      "verse": 24,
      "text_ar": "ولما سمع قايين الكلام الذي نطق به هابيل أخوه، هوذا غضب قايين اشتعل على أخيه هابيل لإعلانه هذا الأمر."
    },
    {
      "chapter": 1,
      "verse": 25,
      "text_ar": "وأسرع قايين وقام، وأخذ القطعة الحديدية من آلة حراثته، والتي ضرب بها أخاه بغتة فقتله، وسفك قايين دم أخيه هابيل على الأرض، وتدفق دم هابيل على الأرض أمام القطيع."
    },
    {
      "chapter": 1,
      "verse": 26,
      "text_ar": "وبعد هذا ندم قايين على قتله أخاه، وحزن حزناً شديداً، وبكى عليه وآلمه ذلك جداً."
    },
    {
      "chapter": 1,
      "verse": 27,
      "text_ar": "وقام قايين وحفر حفرة في الحقل، ووضع فيها جسد أخيه، وواراه التراب."
    },
    {
      "chapter": 1,
      "verse": 28,
      "text_ar": "وعلم الرب ما فعله قايين بأخيه، وتراءى الرب لقايين وقال له: أين هابيل أخوك الذي كان معك؟"
    },
    {
      "chapter": 1,
      "verse": 29,
      "text_ar": "فتظاهر قايين وقال: لا أعلم، أحرّاساً أنا لأخي؟ فقال له الرب: ماذا فعلت؟ صوت دم أخيك يصرخ إليّ من الأرض حيث قتلته."
    },
    {
      "chapter": 1,
      "verse": 30,
      "text_ar": "لأنك قتلت أخاك وتظاهرت أمامي، وتخيلت في قلبك أني لا أراك، ولا أعرف كل أفعالك."
    }
  ]
}
